foldSourceSites.callText:
ranges::fold_left(
        tokens | ranges::views::chunk(batch_size),
        PrefillState{pipeline.start_session()},
        [&](PrefillState state, auto chunk) -> PrefillState {
          const auto batch = chunk | ranges::to<std::vector<int32_t>>();

          if (auto *initial = std::get_if<AttentionState>(&state)) {
            return pipeline.run_batch(std::move(*initial), batch);
          }

          auto &previous = std::get<BatchResult>(state);

          return pipeline.run_batch(std::move(previous.state), batch);
        })

ranges::fold_left(
        ranges::views::iota(0, predict),
        Generation{std::move(std::get<BatchResult>(prefill))},
        [&](Generation state, int index) -> Generation {
          if (std::holds_alternative<GenerationFinished>(state)) {
            return state;
          }

          auto &current = std::get<BatchResult>(state);
          const llama_token token = current.logits.greedy_token();
          if (llama_vocab_is_eog(vocab, token)) {
            return GenerationFinished{};
          }

          std::cout << token_piece(vocab, token) << std::flush;
          if (index + 1 == predict) {
            return GenerationFinished{};
          }

          return pipeline.run_batch(std::move(current.state), {token});
        })

ranges::fold_left(
      ranges::views::iota(first_option, argc) | ranges::views::stride(2),
      AttentionOptions{has_address ? argv[3] : "127.0.0.1:50051"},
      [&](AttentionOptions options, int index) {
        const std::string_view name(argv[index]);
        if (index + 1 == argc) {
          throw std::invalid_argument("missing value for " + std::string(name));
        }
        const char *value = argv[index + 1];
        if (name == "--n_predict") {
          options.n_predict = nano::parse_integer(value, 0, 1048576);
        } else if (name == "--n_ctx") {
          options.n_ctx = nano::parse_integer(value, 1, 1048576);
        } else if (name == "--n_gpu_layers") {
          options.n_gpu_layers = nano::parse_integer(value, -1, 10000);
        } else if (name == "--mode") {
          options.mode = nano::parse_prompt_mode(value);
        } else {
          throw std::invalid_argument("unknown option: " + std::string(name));
        }
        return options;
      })

ranges::fold_left(
      batch_pos | ranges::views::enumerate,
      std::vector<int32_t>(state_rows, -1),
      [state_rows](std::vector<int32_t> sources, const auto &entry) {
        sources[std::get<1>(entry) % state_rows] = std::get<0>(entry);
        return sources;
      })

ranges::fold_left(
      batch_pos | ranges::views::enumerate,
      std::vector<MaskValue>(n_kv * batch_pos.size(), masked),
      [=](std::vector<MaskValue> values, const auto &entry) {
        const int64_t n_visible =
            (static_cast<int64_t>(std::get<1>(entry)) + 1) / ratio;

        GGML_ASSERT(n_visible <= n_kv);

        std::fill_n(values.data() + std::get<0>(entry) * n_kv, n_visible,
                    MaskValue{0});

        return values;
      })

ranges::fold_left(
      ranges::views::iota(uint32_t{0}, hp.n_layer()),
      std::vector<LayerCaches>{},
      [&](std::vector<LayerCaches> storage, uint32_t il) {
        auto context = nano::make_context(16);
        // Cache tensors: [width, 1, rows]; compressor state tensors: [width,
        // rows].
        const auto cache = [&](int64_t width, int64_t rows, ggml_type dtype) {
          return ggml_new_tensor_3d(context.get(), dtype, width, 1, rows);
        };

        const auto state = [&](int64_t width, int64_t rows) -> CompressorCache {
          return {
              ggml_new_tensor_2d(context.get(), GGML_TYPE_F32, width, rows),
              ggml_new_tensor_2d(context.get(), GGML_TYPE_F32, width, rows)};
        };

        const CompressionCache compression = [&]() -> CompressionCache {
          switch (hp.dsv4_compress_ratios[il]) {
          case 0:
            return RawCache{};
          case DSV4_CSA_RATIO:
            return CsaCache{
                cache(hp.n_embd_head_k(), csa_capacity, GGML_TYPE_F16),
                cache(hp.indexer_head_size, csa_capacity, type),
                state(2 * hp.n_embd_head_k(), 2 * DSV4_CSA_RATIO),
                state(2 * hp.indexer_head_size, 2 * DSV4_CSA_RATIO)};
          case DSV4_HCA_RATIO:
            return HcaCache{
                cache(hp.n_embd_head_k(), hca_capacity, GGML_TYPE_F16),
                state(hp.n_embd_head_k(), DSV4_HCA_RATIO)};
          default:
            throw std::invalid_argument(
                "unsupported attention compression ratio");
          }
        }();

        const auto raw = cache(hp.n_embd_head_k(), raw_capacity, GGML_TYPE_F16);
        // Match native KV placement. Putting CPU layers' compressor state on
        // the GPU also moves their normalization and F16 cache rounding there.
        nano::Buffer buffer(
            ggml_backend_alloc_ctx_tensors(context.get(),
                                           compute.layer_backend(model, il)),
            ggml_backend_buffer_free);
        if (!buffer) {
          throw std::runtime_error("failed to allocate attention caches");
        }
        ggml_backend_buffer_clear(buffer.get(), 0);
        storage.push_back(
            {std::move(context), std::move(buffer), raw, compression});
        return storage;
      })

ranges::fold_left(
        ranges::views::iota(uint32_t{0}, info.n_layer()), embedded,
        [&](std::vector<float> input, uint32_t il) {
          const auto &cache = state.cache->layers.at(il);

          const auto attention_output =
              execute_attention(cache, il, positions,
                                input); // [4096,4,T], writes this layer's KV

          const auto ffn_output = ffn.forward(
              info, il, tokens, attention_output); // [4096,4,T], network RPC

          return ffn_output;
        })

ranges::fold_left(
      ranges::views::iota(int64_t{1}, used), expert_view(0),
      [&](ggml_tensor *sum, int64_t slot) {
        return ggml_add(ctx, sum, expert_view(slot));
      })

ranges::fold_left(
      ranges::views::iota(0, ggml_graph_n_nodes(graph)), std::set<ggml_tensor *>{},
      [&](std::set<ggml_tensor *> tensors, int index) {
        const auto node = ggml_graph_node(graph, index);
        tensors.insert(node);
        ranges::for_each(node->src, [&](ggml_tensor *source) {
          if (source) {
            tensors.insert(source);
          }
        });
        return tensors;
      })

ranges::fold_left(
      request.tokens() | ranges::views::enumerate,
      std::vector<std::vector<int32_t>>{},
      [&](std::vector<std::vector<int32_t>> selections, const auto &entry) {
        const size_t token_index = std::get<0>(entry);
        if (hash) {
          std::vector<int32_t> ids(used); // third-party tensor-get output
          ggml_backend_tensor_get(layer.ffn_gate_tid2eid, ids.data(),
              size_t(std::get<1>(entry)) * layer.ffn_gate_tid2eid->nb[1],
              ids.size() * sizeof(int32_t));
          selections.push_back(std::move(ids));
        } else {
          // Match the CPU argsort comparator, including its handling of ties.
          const auto greater_score = [&](int32_t a, int32_t b) {
            return scores[token_index * hp.n_expert + a] >
                   scores[token_index * hp.n_expert + b];
          };
          const auto sorted_ids = ranges::views::iota(int32_t{0}, int32_t(hp.n_expert)) |
              ranges::to<std::vector<int32_t>>() |
              ranges::actions::sort(greater_score);
          const auto ids = sorted_ids |
              ranges::views::take(used) | ranges::to<std::vector<int32_t>>();
          selections.push_back(ids);
        }
        if (!ranges::all_of(selections.back(), [&](int32_t id) {
              return id >= 0 && uint32_t(id) < hp.n_expert;
            })) {
          throw std::runtime_error("router selected an invalid expert ID");
        }
        return selections;
      })

ranges::fold_left(
      ranges::views::iota(uint32_t{0}, model.hparams.n_layer()), FfnRuntime{},
      [&](FfnRuntime state, uint32_t il) {
        const auto start = InferenceClock::now();
        std::fprintf(stderr, "ffn prepare: layer=%u/%u starting\n",
                     il, model.hparams.n_layer());
        const auto placement = ffn_batch_placement(compute, model, il, 1);
        const auto layout = expert_bank_layout(model, il, placement.expert_backends);
        const size_t index = find_or_prepare_expert_bank(state, model, il, layout);
        const auto &weights = state.banks[index]->weights;
        auto router = prepare_ffn_router(compute, model, il, 1);
        auto execution = prepare_ffn_execution(compute, model, il, 1, weights,
                                               placement.matrices);
        state.decode.push_back(std::make_unique<FfnDecodePlan>(FfnDecodePlan{
            index, std::move(router), placement.matrices, std::move(execution)}));
        std::fprintf(stderr,
                     "ffn prepare: layer=%u ready expert_bank=%zu total_banks=%zu elapsed_ms=%.3f\n",
                     il, index, state.banks.size(), elapsed_ms(start));
        return state;
      })

ranges::fold_left(
      ranges::views::iota(size_t{0}, request.n_tokens()), Groups{},
      [&](Groups groups, size_t token) {
        groups[routing.experts[token]].push_back(token);
        return groups;
      })

ranges::fold_left(groups, std::vector<float>(request.hidden().size()),
      [&](std::vector<float> output, const auto &group) {
        fill_expert_weights(bank.copy_views.get(), bank.weights, layer, group.first);
        // Keep singleton prefill groups on the prefill kernel path. SYCL's
        // single-token quantized path uses different activation precision.
        const auto group_tokens = group.second.size() == 1 && request.n_tokens() > 1
            ? std::vector<size_t>{group.second.front(), group.second.front()}
            : group.second;
        const auto &plan = prefill
            ? prefill_execution(state, compute, model, request.layer(),
                                group_tokens.size(), bank.weights, backends)
            : decode.execution;
        fill_ffn_inputs(plan.tensors, routing, request, group_tokens, model.hparams);
        plan.compute();
        const auto values = read_f32(plan.tensors.output);
        return ranges::fold_left(group.second | ranges::views::enumerate,
            std::move(output), [&](std::vector<float> result, const auto &entry) {
              std::copy_n(values.begin() + std::get<0>(entry) * width, width,
                           result.begin() + std::get<1>(entry) * width);
              return result;
            });
      })

ranges::fold_left(group.second | ranges::views::enumerate,
            std::move(output), [&](std::vector<float> result, const auto &entry) {
              std::copy_n(values.begin() + std::get<0>(entry) * width, width,
                           result.begin() + std::get<1>(entry) * width);
              return result;
            })

ranges::fold_left(
        events, State{transport.await_call(), std::move(runtime)},
        [&](State state,
            const std::optional<RpcTransport::Event> &event) {
          auto next = transport.advance(std::move(state.rpc), *event);

          if (auto *ready = std::get_if<RpcTransport::RequestReady>(&next)) {

            const auto reply = handle_request(state.ffn, *ready);

            return State{transport.finish_request(std::move(*ready), reply),
                         std::move(state.ffn)};
          }
          return State{std::move(next), std::move(state.ffn)};
        })

ranges::fold_left(
      ranges::views::iota(1, argc), Parsing{environment_options(), false},
      [&](Parsing parsing, int i) {
        if (parsing.consumed) {
          parsing.consumed = false;
          return parsing;
        }
        const std::string flag(argv[i]);
        if (flag == "--help" || flag == "-h") {
          parsing.options.help = true;
          return parsing;
        }
        if (flag == "--jinja") {
          parsing.options.jinja = true;
          return parsing;
        }
        if (flag == "--no-mmproj-offload") {
          parsing.options.vision_gpu = false;
          return parsing;
        }
        if (flag == "--mmap" || flag == "--no-mmap") {
          parsing.options.load = flag == "--mmap" ? LanguageLoad::Mmap
                                                  : LanguageLoad::Copy;
          return parsing;
        }
        if (flag == "--check-tensors") {
          parsing.options.check_records = true;
          return parsing;
        }
        if (i + 1 == argc)
          throw std::invalid_argument("missing value for " + flag);
        const std::string value(argv[i + 1]);
        if (flag == "-m" || flag == "--model")
          parsing.options.model = value;
        else if (flag == "--mmproj")
          parsing.options.mmproj = value;
        else if (flag == "--moe-experts")
          parsing.options.experts = value;
        else if (flag == "--image")
          parsing.options.images.push_back(value);
        else if (flag == "-p" || flag == "--prompt")
          parsing.options.prompt = value;
        else if (flag == "--moe-slot-bank")
          parsing.options.shared_slot_count =
              uint32_t(nano::parse_integer(value.c_str(), 1, 65536));
        else if (flag == "--moe-decode-window") {
          if (value == "auto")
            parsing.options.cache.reset();
          else
            parsing.options.cache =
                uint32_t(nano::parse_integer(value.c_str(), 0, 1024));
        } else if (flag == "--moe-lookahead")
          parsing.options.lookahead =
              uint32_t(nano::parse_integer(value.c_str(), 0, 256));
        else if (flag == "--moe-prewarm")
          parsing.options.prewarm =
              uint32_t(nano::parse_integer(value.c_str(), 0, 256));
        else if (flag == "--moe-prewarm-file")
          parsing.options.prewarm_file = value;
        else if (flag == "--moe-prewarm-save")
          parsing.options.prewarm_save = value;
        else if (flag == "--moe-io") {
          if (value == "mmap")
            parsing.options.expert_io = ExpertIo::Mmap;
          else if (value == "pread")
            parsing.options.expert_io = ExpertIo::Pread;
          else
            throw std::invalid_argument("--moe-io requires mmap or pread");
        } else if (flag == "-c" || flag == "--ctx-size")
          parsing.options.context_size =
              nano::parse_integer(value.c_str(), 1, 1048576);
        else if (flag == "-n" || flag == "--n-predict") {
          const int predict =
              nano::parse_integer(value.c_str(), -1, 1048576);
          parsing.options.predict =
              predict < 0 ? std::nullopt : std::optional<int>{predict};
        } else if (flag == "-ngl" || flag == "--n-gpu-layers")
          parsing.options.gpu_layers =
              nano::parse_integer(value.c_str(), 0, 1000);
        else if (flag == "-t" || flag == "--threads")
          parsing.options.threads = nano::parse_integer(value.c_str(), 1, 1024);
        else if (flag == "--seed")
          parsing.options.seed =
              nano::parse_integer(value.c_str(), 0, INT32_MAX);
        else if (flag == "--top-k")
          parsing.options.top_k =
              nano::parse_integer(value.c_str(), 0, 1048576);
        else if (flag == "--top-p") {
          size_t parsed_length = 0; // std::stof output parameter
          const float top_p = std::stof(value, &parsed_length);
          if (parsed_length != value.size() || !std::isfinite(top_p) ||
              top_p < 0 || top_p > 1)
            throw std::invalid_argument("invalid top-p");
          parsing.options.top_p = top_p;
        } else if (flag == "--temp") {
          size_t parsed_length = 0; // std::stof output parameter
          const float temperature = std::stof(value, &parsed_length);
          if (parsed_length != value.size() || !std::isfinite(temperature) ||
              temperature < 0)
            throw std::invalid_argument("invalid temperature");
          parsing.options.temperature = temperature;
        } else
          throw std::invalid_argument("unknown option: " + flag);
        parsing.consumed = true;
        return parsing;
      })

ranges::fold_left(
      ranges::views::iota(size_t{0}, tokens.size()) |
          ranges::views::stride(batch_capacity),
      BatchState{std::move(session_state), {}},
      [&](BatchState batch_state, size_t offset) {
        return pipeline.run_batch(
            std::move(batch_state.session_state),
            {tokens.begin() + offset,
             tokens.begin() +
                 std::min(tokens.size(), offset + batch_capacity)});
      })

ranges::fold_left(
      ranges::views::iota(size_t{0}, mtmd_input_chunks_size(chunks)),
      BatchState{std::move(session_state), {}},
      [&](BatchState batch_state, size_t i) {
        const auto *chunk = mtmd_input_chunks_get(chunks, i);

        switch (mtmd_input_chunk_get_type(chunk)) {
        // 文本块可能为空；此时原样传递状态和上一块 logits。
        case MTMD_INPUT_CHUNK_TYPE_TEXT: {
          size_t count = 0; // mtmd C API output

          const auto tokens = mtmd_input_chunk_get_tokens_text(chunk, &count);

          if (!count)
            return batch_state;

          return prefill_text(pipeline, std::move(batch_state.session_state),
                              {tokens, tokens + count});
        }

        case MTMD_INPUT_CHUNK_TYPE_IMAGE: {
          // 本地语言图使用因果 mask，遇到要求非因果图像注意力的配置应明确拒绝。
          if (mtmd_decode_use_non_causal(vision, chunk))
            throw std::invalid_argument(
                "this pipeline requires causal image attention");
          if (mtmd_encode_chunk(vision, chunk))
            throw std::runtime_error("image encoding failed");
          const auto image = mtmd_input_chunk_get_tokens_image(chunk);
          const size_t count = mtmd_input_chunk_get_n_tokens(chunk);
          // 借用 mtmd 输出缓冲，布局为每个图像 token 连续 width 个 float；
          // 在本图像的所有分批语言计算结束前不再调用视觉编码，保证指针有效。
          const auto embeddings =
              mtmd_get_output_embd(vision); // [2048, count] F32，width=2048
          // 图像占用的逻辑 RoPE 位置数可不同于 embedding 数，next_rope 必须采用
          // mtmd 给出的跨度。
          const int base = batch_state.session_state.rope_position;
          const int next_rope = base + mtmd_input_chunk_get_n_pos(chunk);
          const size_t batch_capacity = pipeline.batch_capacity();

          return ranges::fold_left(
              ranges::views::iota(size_t{0}, count) |
                  ranges::views::stride(batch_capacity),
              std::move(batch_state),
              [&](BatchState batch_state, size_t offset) {
                const size_t nt = std::min(batch_capacity, count - offset);
                // 位置按四个轴分段存储；通过解码器坐标 API 保留图像的空间结构。
                // 每个分批使用全图偏移 offset，避免各批图像坐标重新从零开始。
                // positions: 4*nt 个 I32，展平布局 [nt,4]；切出的 embeddings:
                // [2048,nt] F32。
                const auto positions = ranges::views::iota(size_t{0}, 4 * nt) |
                                       ranges::views::transform([&](size_t k) {
                                         const auto pos =
                                             mtmd_image_tokens_get_decoder_pos(
                                                 image, base, offset + k % nt);
                                         switch (k / nt) {
                                         case 0:
                                           return int32_t(pos.t);
                                         case 1:
                                           return int32_t(pos.y);
                                         case 2:
                                           return int32_t(pos.x);
                                         default:
                                           return int32_t(pos.z);
                                         }
                                       }) |
                                       ranges::to<std::vector<int32_t>>();
                return pipeline.run_embeddings(
                    std::move(batch_state.session_state),
                    {embeddings + offset * width,
                     embeddings + (offset + nt) * width},
                    positions, next_rope);
              });
        }
        case MTMD_INPUT_CHUNK_TYPE_AUDIO:
        case MTMD_INPUT_CHUNK_TYPE_COUNT:
          throw std::invalid_argument("only text and image input is supported");
        }
        throw std::invalid_argument("unknown multimodal chunk type");
      })

ranges::fold_left(
              ranges::views::iota(size_t{0}, count) |
                  ranges::views::stride(batch_capacity),
              std::move(batch_state),
              [&](BatchState batch_state, size_t offset) {
                const size_t nt = std::min(batch_capacity, count - offset);
                // 位置按四个轴分段存储；通过解码器坐标 API 保留图像的空间结构。
                // 每个分批使用全图偏移 offset，避免各批图像坐标重新从零开始。
                // positions: 4*nt 个 I32，展平布局 [nt,4]；切出的 embeddings:
                // [2048,nt] F32。
                const auto positions = ranges::views::iota(size_t{0}, 4 * nt) |
                                       ranges::views::transform([&](size_t k) {
                                         const auto pos =
                                             mtmd_image_tokens_get_decoder_pos(
                                                 image, base, offset + k % nt);
                                         switch (k / nt) {
                                         case 0:
                                           return int32_t(pos.t);
                                         case 1:
                                           return int32_t(pos.y);
                                         case 2:
                                           return int32_t(pos.x);
                                         default:
                                           return int32_t(pos.z);
                                         }
                                       }) |
                                       ranges::to<std::vector<int32_t>>();
                return pipeline.run_embeddings(
                    std::move(batch_state.session_state),
                    {embeddings + offset * width,
                     embeddings + (offset + nt) * width},
                    positions, next_rope);
              })

ranges::fold_left(
      images, std::string{}, [](std::string image_markers, const auto &) {
        return image_markers + mtmd_default_marker() + "\n";
      })

ranges::fold_left(
      ranges::views::iota(0, limit),
      Generation{std::move(batch_state), {}, false, 0, 0},
      [&](Generation generation, int) {
        if (generation.done || generation.batch_state.session_state.position >=
                                   options.context_size)
          return generation;

        // prefill/上一步 decode 的最后位置 logits 预测当前 token。
        // 输出后再将 token 送回模型，更新全部层状态并取得下一步 logits。
        const auto token = sample(sampler, generation.batch_state.logits);

        // 终止 token 不输出，也不在此处送回模型；本轮已生成的正文写入聊天历史。
        if (llama_vocab_is_eog(vocab, token)) {
          generation.done = true;
          return generation;
        }

        const auto piece = token_piece(vocab, token);
        std::cout << piece << std::flush;

        generation.text += piece;

        const auto decode_begin = nano::InferenceClock::now();

        generation.batch_state =
            pipeline.run_batch(std::move(generation.batch_state.session_state),
                               {token}, ExecutionPhase::Decode);

        generation.decode_ns += elapsed_ns(decode_begin);
        ++generation.decode_tokens;

        return generation;
      })

ranges::fold_left(std::array{std::move(message), std::move(assistant)},
                        std::move(chat_state.history),
                        [](auto history, const common_chat_msg &message) {
                          history.push_back(message);

                          return history;
                        })

ranges::fold_left(
        lines | ranges::views::take_while(
                    [](const auto &line) { return line.has_value(); }),
        &interactive,
        [&](Interactive *interactive, const std::optional<std::string> &line) {
          if (*line == "/quit" || *line == "/exit")
            interactive->done = true;

          // 同步重置模型缓存、历史、待发图片和采样器，使新对话从空上下文开始。
          else if (*line == "/clear") {
            interactive->chat_state = {
                pipeline.clear_session(
                    std::move(interactive->chat_state.session_state)),
                {}};
            interactive->images.clear();
            llama_sampler_reset(sampler.get());

          } else if (line->rfind("/image ", 0) == 0)
            interactive->images.push_back(line->substr(7));

          else if (!line->empty()) {
            interactive->chat_state =
                turn(options, pipeline, std::move(interactive->chat_state),
                     templates.get(), vision.get(), vocab, sampler.get(), *line,
                     interactive->images);
            interactive->images.clear();
          }

          return interactive;
        })

ranges::fold_left(
          json.at("entries"), std::map<std::string, ExpertSource>{},
          [&](std::map<std::string, ExpertSource> tensors,
              const nlohmann::json &entry) {
            const auto family = entry.at("tensor_family").get<std::string>();

            if (ranges::find(expert_families, family) == expert_families.end())
              throw std::invalid_argument(
                  "unsupported external tensor family: " + family);

            const auto type = expert_type(entry.at("quant_type"));
            const auto shape = entry.at("shape").get<std::array<int64_t, 3>>();

            if (shape[0] <= 0 || shape[1] <= 0 || shape[2] != expert_count ||
                shape[0] % ggml_blck_size(type) != 0)
              throw std::invalid_argument("invalid expert shape");

            // 量化矩阵按块编码，必须通过 ggml_row_size
            // 计算行字节数，不能用元素数乘标量大小。
            const auto bytes =
                checked_mul(ggml_row_size(type, shape[0]), size_t(shape[1]));

            const int layer = entry.at("layer");
            const std::string name = entry.at("tensor_name");
            const auto offset = entry.at("repacked_offset").get<size_t>();
            const auto stride = entry.at("expert_stride").get<size_t>();
            const auto path = manifest.parent_path() /
                              entry.at("repacked_file").get<std::string>();

            // 核对标准张量名、单专家/全部专家字节数，以及最后一个专家是否仍位于文件内。
            if (layer < 0 ||
                name !=
                    "blk." + std::to_string(layer) + "." + family + ".weight" ||
                entry.at("bytes_per_expert").get<size_t>() != bytes ||
                entry.at("exact_byte_length").get<size_t>() !=
                    checked_mul(bytes, expert_count) ||
                stride < checked_add(offset, bytes) ||
                std::filesystem::file_size(path) <
                    checked_add(checked_mul(expert_count - 1, stride),
                                checked_add(offset, bytes)))
              throw std::invalid_argument("invalid expert extent: " + name);

            if (!tensors
                     .emplace(name, ExpertSource{path, type, shape, offset,
                                                 stride, bytes})
                     .second)
              throw std::invalid_argument("duplicate external tensor: " + name);

            return tensors;
          })

