ranges::fold_left(
             ranges::views::iota(size_t{0}) |
                 ranges::views::take_while(
                     [&](size_t) { return progress.filled_bytes < bytes; }),
             &progress,
             [&](Progress *progress, size_t) {
               // iov_base 指向本次尚未填满的目标内存，iov_len 是剩余字节数。
               // destination 由 execute_io_task 选定，可直接指向 bank 槽位，
               // 也可指向稍后要上传设备的主机 staging；它在调用前已经分配。
               // POSIX output descriptor
               iovec out{destination + progress->filled_bytes,
                         bytes - progress->filled_bytes};

               // preadv 同步填充 destination 的剩余前缀；异步性来自后台线程池。
               const auto count = ::preadv(
                   fd, &out, 1, off_t(offset + progress->filled_bytes));

               ++progress->io.read_calls;

               if (count < 0 && errno == EINTR)
                 return progress;
               if (count <= 0)
                 throw std::runtime_error(
                     "failed or truncated positional expert read");

               // 短读时推进“文件偏移”和“目标地址”，下一次补读剩余字节；
               // 直到整个 bytes 范围填满才返回，EINTR 则保持进度重试。
               progress->filled_bytes += size_t(count);
               progress->io.read_bytes += uint64_t(count);

               return progress;
             })

