              return id >= 0 &&
                     size_t(id) < bank_state.frequencies[layer_index].size();
            }))
          throw std::invalid_argument("invalid prewarm expert IDs");
        struct Warming {
          // 接管当前 bank 的槽位状态；按预热表顺序设置本层前几个槽的标签和
          // LRU，结束后交回 prewarming。
