            bank_context.store, bank_context.pool,
            make_cache_read(
                layer_index, prewarming.layer_banks.at(layer_index).records,
                bank_context.store->record_bytes, std::move(warming.missing))));
        prewarming.prewarm_loaded += loaded.record_count;
        prewarming.prewarm_io =
            account_io(prewarming.prewarm_io, loaded, {begin, begin},
                       std::chrono::duration_cast<std::chrono::nanoseconds>(
                           LesClock::now() - begin)
                           .count());
        ++prewarming.prewarm_io.layer_count;
        return prewarming;
      })

