ranges::fold_left(
        model->tensors_by_name,
        std::vector<nano::Buffer>(std::make_move_iterator(&buffer),
                                  std::make_move_iterator(&buffer + 1)),
        [&](std::vector<nano::Buffer> resident_buffers, const auto &entry) {
          const auto &[name, tensor] = entry;

          if (routed_weight(name)) {
            tensor->buffer = nullptr;
            return resident_buffers;
          }

          const size_t offset =
              resident_offset(language_gguf.get(), name, tensor);
          const size_t bytes = ggml_nbytes(tensor);
          const auto type = ggml_backend_buffer_get_type(tensor->buffer);
          const auto device = ggml_backend_buft_get_device(type);

          ggml_backend_dev_props properties{}; // capability API output

          if (device)
            ggml_backend_dev_get_props(device, &properties);

          const bool cpu = device
                               ? properties.type == GGML_BACKEND_DEVICE_TYPE_CPU
                               : ggml_backend_buft_is_host(type);

          // CPU 专用布局必须整张导入并重排，随后释放源映射中的完整页。
          if (cpu && type != ggml_backend_cpu_buffer_type()) {
            auto buffer = allocate_resident(tensor, type);

            ggml_backend_tensor_set(tensor, mapping->at(offset, bytes), 0,
                                    bytes);

            mapping->release_pages(offset, bytes);

            resident_buffers.push_back(std::move(buffer));

            return resident_buffers;
          }

          if (cpu) {
            bind_mapped_resident(tensor, resident_buffers.front().get(),
                                 mapping->at(offset, bytes));

            return resident_buffers;
          }

          if (properties.caps.buffer_from_host_ptr) {
            // 设备导入与普通 CPU 绑定有不同的 buffer 所有权；单独复用本设备
            // 已导入的映射，不能把 GPU 张量绑定到 CPU buffer。
            const auto existing =
                ranges::find_if(resident_buffers, [&](const auto &buffer) {
                  return ggml_backend_buffer_get_base(buffer.get()) ==
                             mapping->address &&
                         ggml_backend_buft_get_device(
                             ggml_backend_buffer_get_type(buffer.get())) ==
                             device;
                });

            if (existing != resident_buffers.end()) {
              bind_mapped_resident(tensor, existing->get(),
                                   mapping->at(offset, bytes));
              return resident_buffers;
            }

            // 最大常驻张量只供设备导入映射使用；不进入可写 resident_buffers
            // 累加器。
            const size_t max_resident_bytes = ranges::fold_left(
                model->tensors_by_name, size_t{0},
                [](size_t max_resident_bytes, const auto &entry) {
                  return routed_weight(entry.first)
                             ? max_resident_bytes
                             : std::max(max_resident_bytes,
                                        ggml_nbytes(entry.second));
                });

            nano::Buffer buffer(ggml_backend_dev_buffer_from_host_ptr(
                                    device, mapping->address, mapping->size,
                                    max_resident_bytes),
                                ggml_backend_buffer_free);

            if (!buffer)
              throw std::runtime_error(
                  "cannot import mapped weights on model device");

            ggml_backend_buffer_set_usage(buffer.get(),
                                          GGML_BACKEND_BUFFER_USAGE_WEIGHTS);

            bind_mapped_resident(tensor, buffer.get(),
                                 mapping->at(offset, bytes));

            resident_buffers.push_back(std::move(buffer));

            return resident_buffers;
          }

          // 无法导入映射的设备独立分配，再从映射上传原始量化字节。
          auto buffer = allocate_resident(tensor, type);

          ggml_backend_tensor_set(tensor, mapping->at(offset, bytes), 0, bytes);

          resident_buffers.push_back(std::move(buffer));

          return resident_buffers;
        })

