      [&](std::vector<nano::Buffer> resident_buffers, const auto &entry) {
        const auto &[name, tensor] = entry;

        if (routed_weight(name)) {
          tensor->buffer = nullptr;
          return resident_buffers;
        }

        const size_t offset =
            resident_offset(language_gguf.get(), name, tensor);
        const size_t bytes = ggml_nbytes(tensor);
        const auto type = ggml_backend_buffer_get_type(tensor->buffer);
        const auto device = ggml_backend_buft_get_device(type);

        ggml_backend_dev_props properties{}; // capability API output
        if (device)
          ggml_backend_dev_get_props(device, &properties);

        const bool cpu = device
                             ? properties.type == GGML_BACKEND_DEVICE_TYPE_CPU
                             : ggml_backend_buft_is_host(type);

        auto buffer = allocate_resident(tensor, type);

        file.seekg(std::streamoff(offset));

        if (cpu && type != ggml_backend_cpu_buffer_type()) {
          // CPU_REPACK 的 set_tensor 契约要求整张原始张量，不能分块。
          std::vector<char> staging(bytes); // stream API output

          if (!file.read(staging.data(), staging.size()))
            throw std::runtime_error("truncated CPU resident weight: " + name);

          ggml_backend_tensor_set(tensor, staging.data(), 0, staging.size());
        } else {
          constexpr size_t chunk = 8 * 1024 * 1024;

          // 累加器只承载被流填充的暂存字节；目标张量是归约外的固定输入。
          ranges::fold_left(
              ranges::views::iota(size_t{0}, bytes) |
                  ranges::views::stride(chunk),
              std::vector<char>(std::min(bytes, chunk)),
              [&](std::vector<char> staging, size_t start) {
                const size_t length = std::min(chunk, bytes - start);

                if (!file.read(staging.data(), length))
                  throw std::runtime_error("truncated resident weight: " +
                                           name);

                ggml_backend_tensor_set(tensor, staging.data(), start, length);

                return staging;
              });
        }

        // 两种复制方式此时都已完成安装，后续只转交相同的 buffer 所有权。
        resident_buffers.push_back(std::move(buffer));

        return resident_buffers;
      })

ranges::fold_left(
          ranges::views::iota(uint32_t{0}, model.hparams.n_layer()),
          ArenaSizes{}, [&](ArenaSizes sizes, uint32_t layer) {
            const auto &bank =
                key.phase == ExecutionPhase::Decode &&
                        bank_context.layout.layers[layer].slot_count
                    ? bank_state.layer_banks.at(layer)
                    : bank_state.shared_bank;

            const auto routing_graph =
                build_routing_graph(caches[layer], key, layer);

            const auto shared_expert_graph =
                build_shared_graph(layer, routing_graph);

            const auto routed_expert_graph =
                build_routed_graph(layer, routing_graph, shared_expert_graph,
                                   bank.up, bank.gate, bank.down);

            sizes.routing =
                std::max(sizes.routing, bytes(routing_graph.compute_graph));
            sizes.shared = std::max(sizes.shared,
                                    bytes(shared_expert_graph.compute_graph));
            sizes.routed = std::max(sizes.routed,
                                    bytes(routed_expert_graph.compute_graph));

            return sizes;
          })

ranges::fold_left(
        ranges::views::iota(uint32_t{0}, model.hparams.n_layer()),
        LayerExecution{std::move(session_state.caches),
                       std::move(session_state.bank_state),
                       std::move(session_state.graph_cache), nullptr},
        [&](LayerExecution layer_execution, uint32_t layer) {
          auto &bank_state = layer_execution.bank_state;
          auto &graph_cache = layer_execution.graph_cache;

          // build/get graphs
          if (layer == 0) {
            const auto graphs_begin = nano::InferenceClock::now();

            const auto language_graphs_found = graph_cache.graphs.find(key);

            if (language_graphs_found != graph_cache.graphs.end()) {
              language_graphs_found->second->age = ++graph_cache.tick;

              ++bank_state.counters.graph_reuses;
            } else {
              if (graph_cache.graphs.size() >= 4) {
                const auto language_graphs_oldest = ranges::min_element(
                    graph_cache.graphs, [](const auto &a, const auto &b) {
                      return a.second->age < b.second->age;
                    });

                graph_cache.graphs.erase(language_graphs_oldest);
              }

              auto language_graphs = build_language_graphs(
                  layer_execution.caches, bank_state, key);

              language_graphs->age = ++graph_cache.tick;

              graph_cache.graphs.emplace(key, std::move(language_graphs));

              ++bank_state.counters.graph_builds;
            }

            if (profile)
              std::fprintf(stderr,
                           "PROFILE graphs tokens=%zu elapsed_ms=%.3f\n", nt,
                           nano::elapsed_ms(graphs_begin));
          }

          auto &language_graphs = *graph_cache.graphs.at(key);
          auto &layer_graphs = language_graphs.layers[layer];

          const auto layer_begin = nano::InferenceClock::now();

          auto &routing_graph = layer_graphs.routing_graph;

          if (layer_execution.hidden)
            ggml_backend_tensor_copy(layer_execution.hidden,
                                     routing_graph.hidden);

          else
            upload_input(routing_graph.hidden, input);

          static_assert(std::variant_size_v<AttentionInputs> == 2);
          // DeltaNet 没有逐批主机输入；FullAttention 明确上传坐标和
          // mask。
          if (const auto *attention_inputs_full =
                  std::get_if<FullAttentionInputs>(
                      &routing_graph.attention_inputs)) {
            ggml_backend_tensor_set(
                attention_inputs_full->positions, positions.data(), 0,
                ggml_nbytes(attention_inputs_full->positions));

            ggml_backend_tensor_set(
                attention_inputs_full->cache_indices, indices.data(), 0,
                ggml_nbytes(attention_inputs_full->cache_indices));

            ggml_backend_tensor_set(attention_inputs_full->mask, masks.data(),
                                    0,
                                    ggml_nbytes(attention_inputs_full->mask));
          }

          // 执行 attention（写本层 KV/递归状态），再读取真实路由和预测。
          const auto routing_begin = nano::InferenceClock::now();

          execute_compute_graph(routing_graph.compute_graph);

          if (profile)
            nano::report_layer_time("PROFILE routing", layer, nt,
                                    routing_begin);

          const auto selected = tensor_ids(routing_graph.routing.selected);

          auto &shared_expert_graph = layer_graphs.shared_expert_graph;

          auto &routed_expert_graph = layer_graphs.routed_expert_graph;

          // 这两个操作只执行已建好的算术图，不解释阶段或读取凭据。
          const auto compute_shared = [&] {
            const auto shared_begin = nano::InferenceClock::now();

            execute_compute_graph(shared_expert_graph.compute_graph);

            if (profile)
              nano::report_layer_time("PROFILE shared", layer, nt,
                                      shared_begin);
          };

          const auto compute_routed =
              [&](const std::vector<int32_t> &slot_ids) {
                ggml_backend_tensor_set(
                    routed_expert_graph.slot_ids, slot_ids.data(), 0,
                    ggml_nbytes(routed_expert_graph.slot_ids));

                const auto routed_begin = nano::InferenceClock::now();

                execute_compute_graph(routed_expert_graph.compute_graph);

                if (profile)
                  nano::report_layer_time("PROFILE routed", layer, nt,
                                          routed_begin);
              };

          switch (phase) {
          case ExecutionPhase::Prefill: {
            if (bank_state.pending)
              throw std::logic_error("prefill cannot consume decode prefetch");

            auto plan =
                plan_prefill(index, bank_context, bank_state, layer, selected);

            const size_t copied_count = plan.copies.size();

            auto copy_ticket = start_prefill_copies(
                bank_context, bank_state, layer, std::move(plan.copies));

            auto demand_read_ticket = start_shared_read(
                bank_context.store, bank_context.pool, std::move(plan.read));

            bank_state.slots = std::move(plan.slots);

            const auto shared_begin = LesClock::now();

            compute_shared();

            const auto wait_begin = LesClock::now();

            const auto demand_loaded =
                finish_shared_read(std::move(demand_read_ticket));

            finish_host_copies(std::move(copy_ticket));

            record_prefill(bank_state, layer, selected, copied_count,
                           demand_loaded, {shared_begin, wait_begin},
                           elapsed_ns(wait_begin));

            auto retention_ticket =
                begin_retain_prefill(bank_context, bank_state, layer, selected);

            compute_routed(plan.slot_ids);

            // 下一层会覆盖共享 bank；先汇合对它的留存读取。
            finish_host_copies(std::move(retention_ticket));
            break;
          }
          case ExecutionPhase::Decode: {
            const auto window = bank_context.layout.layers.at(layer);

            if (!window.slot_count) {
              if (bank_state.pending)
                throw std::logic_error(
                    "shared decode cannot consume cache prefetch");

              auto plan = plan_shared_decode(index, bank_context, bank_state,
                                             layer, selected);

              auto demand_read_ticket = start_shared_read(
                  bank_context.store, bank_context.pool, std::move(plan.read));

              bank_state.slots = std::move(plan.slots);

              const auto shared_begin = LesClock::now();

              compute_shared();

              const auto wait_begin = LesClock::now();

              const auto demand_loaded =
                  finish_shared_read(std::move(demand_read_ticket));

              record_shared_decode(bank_state, layer, selected, demand_loaded,
                                   {shared_begin, wait_begin},
                                   elapsed_ns(wait_begin));

              compute_routed(plan.slot_ids);
            } else if (!bank_state.pending) {
              auto plan = plan_cache_decode(index, bank_context, bank_state,
                                            layer, selected);

              auto demand_read_ticket = start_cache_read(
                  bank_context.store, bank_context.pool, std::move(plan.read));

              bank_state.slots = std::move(plan.slots);

              const auto shared_begin = LesClock::now();

              compute_shared();

              const auto wait_begin = LesClock::now();

              const auto demand_loaded =
                  finish_cache_read(std::move(demand_read_ticket));

              record_cache_decode(bank_state, layer, selected,
                                  plan.prefetched_count, demand_loaded,
                                  {shared_begin, wait_begin},
                                  elapsed_ns(wait_begin));

              if (layer + 1 < bank_context.layout.layers.size())
                bank_state = begin_decode_prefetch(
                    bank_context, std::move(bank_state), layer + 1,
                    tensor_ids(routing_graph.routing.predicted_next));

              compute_routed(plan.slot_ids);
            } else {
              if (bank_state.pending->layer != layer)
                throw std::logic_error("LES next-layer prefetch mismatch");

              auto pending = std::move(*bank_state.pending);

              bank_state.pending.reset();

              const auto started = LesClock::now();

              if (window.slot_count <
                  size_t(index.expert_used_count) + pending.slots.size()) {
                // 缓存不足以保护在飞槽并放入全部真实路由；先安装，再规划复用。
                const auto prefetch_loaded =
                    finish_cache_read(std::move(pending.read_ticket));

                const auto early_wait_ns = elapsed_ns(started);

                auto plan = plan_cache_decode(index, bank_context, bank_state,
                                              layer, selected, pending.keys);

                auto demand_read_ticket =
                    start_cache_read(bank_context.store, bank_context.pool,
                                     std::move(plan.read));

                bank_state.slots = std::move(plan.slots);

                const auto shared_begin = LesClock::now();

                compute_shared();

                const auto wait_begin = LesClock::now();

                const auto demand_loaded =
                    finish_cache_read(std::move(demand_read_ticket));

                record_cache_decode(bank_state, layer, selected,
                                    plan.prefetched_count, demand_loaded,
                                    {shared_begin, wait_begin},
                                    early_wait_ns + elapsed_ns(wait_begin));

                record_cache_prefetch(bank_state, plan.prefetched_count,
                                      pending.keys.size(), prefetch_loaded,
                                      demand_loaded, {pending.issued, started},
                                      {shared_begin, wait_begin});

                if (layer + 1 < bank_context.layout.layers.size())
                  bank_state = begin_decode_prefetch(
                      bank_context, std::move(bank_state), layer + 1,
                      tensor_ids(routing_graph.routing.predicted_next));

                compute_routed(plan.slot_ids);
              } else {
                // 保留在飞读取的锁槽；需求读取和共享算术仍可并行。
                auto plan =
                    plan_cache_decode(index, bank_context, bank_state, layer,
                                      selected, pending.keys, pending.slots);

                auto demand_read_ticket =
                    start_cache_read(bank_context.store, bank_context.pool,
                                     std::move(plan.read));

                bank_state.slots = std::move(plan.slots);

                const auto shared_begin = LesClock::now();

                compute_shared();

                const auto wait_begin = LesClock::now();

                const auto prefetch_loaded =
                    finish_cache_read(std::move(pending.read_ticket));

                const auto demand_loaded =
                    finish_cache_read(std::move(demand_read_ticket));

                record_cache_decode(bank_state, layer, selected,
                                    plan.prefetched_count, demand_loaded,
                                    {shared_begin, wait_begin},
                                    elapsed_ns(wait_begin));

                record_cache_prefetch(bank_state, plan.prefetched_count,
                                      pending.keys.size(), prefetch_loaded,
                                      demand_loaded, {pending.issued, started},
                                      {shared_begin, wait_begin});

                if (layer + 1 < bank_context.layout.layers.size())
                  bank_state = begin_decode_prefetch(
                      bank_context, std::move(bank_state), layer + 1,
                      tensor_ids(routing_graph.routing.predicted_next));

                compute_routed(plan.slot_ids);
              }
            }
            break;
          }
          }

          if (profile)
            nano::report_layer_time("PROFILE layer", layer, nt, layer_begin);

          layer_execution.hidden = routed_expert_graph.hidden;
          return layer_execution;
        })

ranges::fold_left(
      ranges::views::iota(0, layer_count), nlohmann::json::array(),
      [&](nlohmann::json entries, int layer_index) {
        const auto filename = "layer_" + std::to_string(layer_index) + ".bin";
        std::ofstream packed(directory / filename,
                             std::ios::binary); // file output API
        // stride 从零开始，按 gate/up/down
        // 累加单专家矩阵字节数，最终作为打包记录的专家间步长。
        const auto stride = ranges::fold_left(
            minicpm::expert_families, size_t{0},
            [&](size_t stride, const char *family) {
              return stride +
                     ggml_get_tensor(tensors.get(),
                                     ("blk." + std::to_string(layer_index) +
                                      "." + family + ".weight")
                                         .c_str())
                         ->nb[2];
            });
        ranges::for_each(ranges::views::iota(0, 16), [&](int expert) {
          ranges::for_each(minicpm::expert_families, [&](const char *family) {
            const auto tensor = ggml_get_tensor(
                tensors.get(), ("blk." + std::to_string(layer_index) + "." +
                             family + ".weight")
                                .c_str());
            packed.write(static_cast<char *>(tensor->data) +
                             expert * tensor->nb[2],
                         tensor->nb[2]);
          });
        });
        struct Progress {
          // 接续之前层的 manifest
          // 条目；本层每处理一个矩阵族追加一条，结束后交回外层条目归约。
          nlohmann::json entries;
          // 当前矩阵在打包专家记录内的字节偏移，初始零；每步增加该矩阵单专家字节数，供下一矩阵记录偏移。
          size_t offset;
        };
        return ranges::fold_left(
                   minicpm::expert_families, Progress{std::move(entries), 0},
                   [&](Progress progress, const char *family) {
                     const std::string name = "blk." +
                                              std::to_string(layer_index) +
                                              "." + family + ".weight";
                     const auto tensor =
                         ggml_get_tensor(tensors.get(), name.c_str());
                     const auto type =
                         minicpm::canonical_type_name(tensor->type);
                     progress.entries.push_back(
                         {{"layer", layer_index},
                          {"tensor_family", family},
                          {"tensor_name", name},
                          {"quant_type", type},
                          {"shape", {tensor->ne[0], tensor->ne[1], 16}},
                          {"exact_byte_length", ggml_nbytes(tensor)},
                          {"bytes_per_expert", tensor->nb[2]},
                          {"repacked_file", filename},
                          {"repacked_offset", progress.offset},
                          {"expert_stride", stride}});
                     progress.offset += tensor->nb[2];
                     return progress;
                   })
            .entries;
      })

ranges::fold_left(
            minicpm::expert_families, size_t{0},
            [&](size_t stride, const char *family) {
              return stride +
                     ggml_get_tensor(tensors.get(),
                                     ("blk." + std::to_string(layer_index) +
                                      "." + family + ".weight")
                                         .c_str())
                         ->nb[2];
            })

ranges::fold_left(
                   minicpm::expert_families, Progress{std::move(entries), 0},
