ranges::fold_left(ranges::views::iota(size_t{0}, size_t{40}),
                        std::array<bool, 40>{}, [](auto flags, size_t i) {
                          flags[i] = (i + 1) % 4 != 0;
                          return flags;
                        })

ranges::fold_left(
        ranges::views::iota(0, 3), pipeline.start_session(),
        [&](minicpm::SessionState session_state, int step) {
          const std::vector<int32_t> token{3 + step};
          // batch 初值由 get_one 包装本批 token
          // 地址与数量；描述字段之后不修改， llama_decode 只读取输入而更新 ref
          // 的 KV/递归状态，不回写 tokens。
          llama_batch batch =
              llama_batch_get_one(const_cast<int32_t *>(token.data()), 1);
          require(llama_decode(ref.get(), batch) == 0,
                  "40-layer reference decode failed");
          auto actual =
              pipeline.run_batch(std::move(session_state), token,
                                 step == 0 ? minicpm::ExecutionPhase::Prefill
                                           : minicpm::ExecutionPhase::Decode);
          const auto expected = llama_get_logits_ith(ref.get(), -1);
          require(ranges::all_of(
                      ranges::views::iota(size_t{0}, actual.logits.size()),
                      [&](size_t i) {
                        return std::isfinite(actual.logits[i]) &&
                               std::abs(actual.logits[i] - expected[i]) <=
                                   2e-4f + 2e-4f * std::abs(expected[i]);
                      }),
                  "40-layer LES/reference logits mismatch");
          return std::move(actual.session_state);
        })

ranges::fold_left(
      index.tensors, std::map<std::string, minicpm::ExpertSource>{},
      [&](std::map<std::string, minicpm::ExpertSource> scattered_tensors,
          const auto &entry) {
        const auto &[name, source] = entry;
        const auto path = directory / (name + ".bin");
        std::filesystem::copy_file(
            source.path, path,
            std::filesystem::copy_options::overwrite_existing);
        scattered_tensors.emplace(
            name,
            minicpm::ExpertSource{path, source.type, source.shape,
                                  source.offset, source.stride, source.bytes});
        return scattered_tensors;
      })

ranges::fold_left(
      std::array{2},
      minicpm::apply_prewarm(bank_context,
                             minicpm::make_bank(index, bank_context),
                             config.prewarm_table),
      [&](minicpm::BankState bank_state, uint32_t layer) {
        const auto cache_keys = bank_state.slots.keys;
        const auto window = bank_context.layout.layers[layer];
        const auto slot = minicpm::metadata_slot(window, 7);
        require(slot == window.begin + 7 &&
                    minicpm::bank_slot(window, slot) == 7,
                "slot conversion lost window origin");
        rejects([&] { minicpm::bank_slot(window, {window.begin - 1}); });
        rejects([&] {
          minicpm::bank_slot(window, {window.begin + window.slot_count});
        });
        rejects([&] { minicpm::metadata_slot(window, {window.slot_count}); });

        const std::vector<int32_t> selected{7, 0,  8, 3, 9, 2, 10, 1,
                                            1, 10, 2, 9, 3, 8, 0,  7};
        const std::vector<char> untouched(
            ggml_nbytes(bank_state.shared_bank.records), char(0x55));
        ggml_backend_tensor_set(bank_state.shared_bank.records,
                                untouched.data(), 0, untouched.size());
        auto plan = minicpm::plan_prefill(index, bank_context, bank_state,
                                          layer, selected);
        require(plan.copies.size() == 5 && plan.read.missing.size() == 3 &&
                    bank_state.slots.keys == cache_keys,
                "prefill copy/read planning or published metadata mismatch");
        require(plan.slot_ids[1] == 0 &&
                    *minicpm::resident_slot(bank_state.slots, window,
                                            {layer, 0}) ==
                        window.begin + 7,
                "prefill cache source was confused with shared destination");
        std::vector<char> actual(bank_context.store->record_bytes);
        ggml_backend_tensor_get(bank_state.shared_bank.records,
                                actual.data(), 0, actual.size());
        require(actual == std::vector<char>(actual.size(), char(0x55)),
                "read-only prefill planning wrote shared weights");
        require(plan.copies.size() == 5 &&
                    plan.copies.front().slot_source == 7 &&
                    plan.copies.front().slot_destination == 0,
                "prefill copy plan lost source/destination slots");

        const size_t copied = plan.copies.size();
        auto copy_ticket = minicpm::start_prefill_copies(
            bank_context, bank_state, layer, std::move(plan.copies));
        auto demand_read_ticket = minicpm::start_shared_read(
            bank_context.store, bank_context.pool, std::move(plan.read));
        bank_state.slots = std::move(plan.slots);
        require(ranges::equal(cache_keys | ranges::views::drop(256),
                              bank_state.slots.keys | ranges::views::drop(256)),
                "prefill changed independent decode cache labels");
        const auto demand_loaded =
            minicpm::finish_shared_read(std::move(demand_read_ticket));
        minicpm::finish_host_copies(std::move(copy_ticket));
        minicpm::record_prefill(bank_state, layer, selected, copied,
                                demand_loaded, {}, 0);
        const auto &slot_ids = plan.slot_ids;
        minicpm::finish_host_copies(minicpm::begin_retain_prefill(
            bank_context, bank_state, layer, selected));
        require(bank_state.counters.prefill.hits == 5 &&
                    bank_state.counters.prefill.misses == 3 &&
                    bank_state.counters.prefill.read_calls == 3,
                "prefill copied-cache and demand accounting mixed");
        ranges::for_each(
            selected | ranges::views::enumerate, [&](const auto &entry) {
              const auto [i, expert] = entry;
              const size_t slot = size_t(slot_ids[i]);
              require(bank_state.slots.keys[slot] ==
                          minicpm::ExpertKey{layer, expert},
                      "prefill lost repeated top-k/token ordering");
              std::vector<char> expected(bank_context.store->record_bytes),
                  actual(expected.size());
              minicpm::read_record(*bank_context.store, {layer, expert},
                                   expected.data());
              ggml_backend_tensor_get(bank_state.shared_bank.records,
                                      actual.data(), slot * actual.size(),
                                      actual.size());
              require(actual == expected,
                      "prefill shared bytes do not match routed expert");
            });
        verify_cache_bytes(bank_context, bank_state);
        const auto frequencies = bank_state.frequencies;
        const auto counters = bank_state.counters;
        const auto records = bank_state.shared_bank.records;
        bank_state = minicpm::apply_prewarm(bank_context, std::move(bank_state),
                                            config.prewarm_table);
        require(
            bank_state.frequencies == frequencies &&
                bank_state.shared_bank.records == records &&
                bank_state.counters.prefill.layer_count ==
                    counters.prefill.layer_count &&
                bank_state.counters.prefill.hits == counters.prefill.hits &&
                bank_state.counters.prefill.misses == counters.prefill.misses &&
                bank_state.counters.prefill.read_bytes ==
                    counters.prefill.read_bytes &&
                bank_state.counters.prewarm_from_prefill ==
                    counters.prewarm_from_prefill &&
                bank_state.counters.prewarm_loaded ==
                    counters.prewarm_loaded + 32,
            "prewarm changed state outside its accumulator");
        verify_cache_bytes(bank_context, bank_state);
        return bank_state;
      })

ranges::fold_left(
            layers | ranges::views::enumerate,
            minicpm::make_bank(index, bank_context),
            [&](minicpm::BankState bank_state, const auto &entry) {
              const auto [step, layer] = entry;
              if (step == 0) {
                const auto selected_prefill =
                    ranges::views::iota(0, 16) |
                    ranges::to<std::vector<int32_t>>();
                auto plan = minicpm::plan_prefill(
                    index, bank_context, bank_state, layer, selected_prefill);
                auto demand_read_ticket = minicpm::start_shared_read(
                    bank_context.store, bank_context.pool,
                    std::move(plan.read));
                bank_state.slots = std::move(plan.slots);
                const auto demand_loaded =
                    minicpm::finish_shared_read(std::move(demand_read_ticket));
                minicpm::record_prefill(bank_state, layer, selected_prefill,
                                        plan.copies.size(), demand_loaded, {},
                                        0);
              }
              const auto keys = bank_state.slots.keys;
              const auto frequencies = bank_state.frequencies[layer];
              auto plan = minicpm::plan_shared_decode(
                  index, bank_context, bank_state, layer, selected);
              require(bank_state.slots.keys == keys &&
                          plan.read.missing.size() == selected.size(),
                      "shared decode planning published metadata or reused old "
                      "weights");
              rejects<std::logic_error>([&] {
                minicpm::plan_cache_decode(index, bank_context, bank_state,
                                           layer, selected);
              });
              auto demand_read_ticket = minicpm::start_shared_read(
                  bank_context.store, bank_context.pool, std::move(plan.read));
              bank_state.slots = std::move(plan.slots);
              const auto demand_loaded =
                  minicpm::finish_shared_read(std::move(demand_read_ticket));
              minicpm::record_shared_decode(bank_state, layer, selected,
                                            demand_loaded, {}, 0);
              const auto &slot_ids = plan.slot_ids;
              ranges::for_each(
                  selected | ranges::views::enumerate, [&](const auto &entry) {
                    const auto [i, expert] = entry;
                    const auto slot = size_t(slot_ids[i]);
                    require(bank_state.slots.keys[slot] ==
                                    minicpm::ExpertKey{layer, expert} &&
                                bank_state.frequencies[layer][expert] ==
                                    frequencies[expert] + 1,
                            "shared decode lost routing order, identity or "
                            "frequency");
                    std::vector<char> expected(
                        bank_context.store->record_bytes),
                        actual(expected.size()); // read API outputs
                    minicpm::read_record(*bank_context.store, {layer, expert},
                                         expected.data());
                    ggml_backend_tensor_get(bank_state.shared_bank.records,
                                            actual.data(), slot * actual.size(),
                                            actual.size());
                    require(actual == expected,
                            "shared decode installed wrong bytes");
                  });
              require(ranges::none_of(
                          bank_state.slots.keys |
                              ranges::views::drop(selected.size()),
                          [](const auto &key) { return key.has_value(); }),
                      "shared decode retained unused shared labels");
              return bank_state;
            })

ranges::fold_left(
        std::array{0},
        minicpm::begin_decode_prefetch(bank_context,
                                       minicpm::make_bank(index, bank_context),
                                       0, predicted),
        [&](minicpm::BankState bank_state, uint32_t layer) {
          auto pending = std::move(*bank_state.pending);
          bank_state.pending.reset();
          const auto prefetch_loaded =
              minicpm::finish_cache_read(std::move(pending.read_ticket));
          auto plan = minicpm::plan_cache_decode(
              index, bank_context, bank_state, layer, selected, pending.keys);
          auto demand_read_ticket = minicpm::start_cache_read(
              bank_context.store, bank_context.pool, std::move(plan.read));
          bank_state.slots = std::move(plan.slots);
          const auto demand_loaded =
              minicpm::finish_cache_read(std::move(demand_read_ticket));
          minicpm::record_cache_decode(bank_state, layer, selected,
                                       plan.prefetched_count, demand_loaded,
                                       {}, 0);
          minicpm::record_cache_prefetch(bank_state, plan.prefetched_count,
                                         pending.keys.size(), prefetch_loaded,
                                         demand_loaded, {}, {});
          const auto &slot_ids = plan.slot_ids;
          require(
              slot_ids.size() == 8 && !bank_state.pending &&
                  bank_state.counters.prefetch_used == (correct ? 8 : 0) &&
                  bank_state.counters.prefetch_wasted == (correct ? 0 : 8) &&
                  bank_state.counters.decode.hits == 0 &&
                  bank_state.counters.decode.misses == 8 &&
                  bank_state.counters.decode.read_calls == (correct ? 8 : 16),
              "early-joined prefetch was re-consumed or accounted as resident");
          return bank_state;
        })

ranges::fold_left(
            std::array{0}, minicpm::make_bank(index, bank_context),
            [&](minicpm::BankState bank_state, uint32_t layer) {
              bank_state = minicpm::begin_decode_prefetch(
                  bank_context, std::move(bank_state), layer, wrong);
              require(bank_state.pending &&
                          bank_state.pending->keys.size() == 8,
                      "LES did not issue asynchronous predictions");
              auto pending = std::move(*bank_state.pending);
              bank_state.pending.reset();
              auto plan = minicpm::plan_cache_decode(
                  index, bank_context, bank_state, layer, selected,
                  pending.keys, pending.slots);
              auto demand_read_ticket = minicpm::start_cache_read(
                  bank_context.store, bank_context.pool, std::move(plan.read));
              bank_state.slots = std::move(plan.slots);
              const auto prefetch_loaded =
                  minicpm::finish_cache_read(std::move(pending.read_ticket));
              const auto demand_loaded =
                  minicpm::finish_cache_read(std::move(demand_read_ticket));
              minicpm::record_cache_decode(bank_state, layer, selected,
                                           plan.prefetched_count,
                                           demand_loaded, {}, 0);
              minicpm::record_cache_prefetch(
                  bank_state, plan.prefetched_count, pending.keys.size(),
                  prefetch_loaded, demand_loaded, {}, {});
              const auto &slot_ids = plan.slot_ids;
              require(
                  slot_ids.size() == 8 &&
                      bank_state.counters.prefetch_used == 0 &&
                      bank_state.counters.prefetch_wasted == 8 &&
                      bank_state.counters.decode.misses == 8 &&
                      bank_state.counters.decode.read_bytes ==
                          16 * bank_context.store->record_bytes,
                  "wrong prefetch demand fallback or byte accounting mismatch");
              require(mode == minicpm::ExpertIo::Mmap
                          ? bank_state.counters.decode.read_calls == 0 &&
                                bank_state.counters.decode.mapped_records == 16
                          : bank_state.counters.decode.read_calls == 16 &&
                                bank_state.counters.decode.mapped_records == 0,
                      "mmap/pread counters mixed");
              verify_cache_bytes(bank_context, bank_state);
              const auto repeat = minicpm::plan_cache_decode(
                  index, bank_context, bank_state, 0, selected);
              require(repeat.prefetched_count == 0 &&
                          repeat.read.missing.empty(),
                      "exact-demand experts did not remain cached");
              // Wrong predictions are retained in the unified window, rather
              // than being immediately thrown away. They can become ordinary
              // hits next time.
              const auto next = minicpm::plan_cache_decode(
                  index, bank_context, bank_state, 0, wrong);
              require(
                  next.prefetched_count == 0 && next.read.missing.empty(),
                  "unused predictions were not retained in the unified cache");
              const auto broken = truncated_store(*bank_context.store);
              const bool failed = [&] {
                try {
                  minicpm::finish_shared_read(minicpm::start_shared_read(
                      broken, bank_context.pool,
                      minicpm::make_shared_read(
                          0, bank_state.shared_bank.records,
                          bank_context.store->record_bytes,
                          {{0, 0}})));
                  return false;
                } catch (const std::runtime_error &) {
                  return true;
                }
              }();
              require(failed, "asynchronous I/O error was swallowed");
              return bank_state;
            })

ranges::fold_left(
        std::array<int, 5>{255, 1, 1, 2, 1},
        Compared{pipeline.start_session(), pipeline.start_session()},
        [&](auto sessions, int count) {
          const auto tokens =
              ranges::views::iota(0, count) |
              ranges::views::transform([&](int i) {
                return int32_t(
                    (sessions.session_state_cached.position + i) % 29 + 2);
              }) |
              ranges::to<std::vector<int32_t>>();
          llama_batch batch = llama_batch_get_one(
              const_cast<int32_t *>(tokens.data()), tokens.size());
          require(llama_decode(ref.get(), batch) == 0,
                  "cache-variant reference decode failed");
          const auto phase = count == 1 ? minicpm::ExecutionPhase::Decode
                                        : minicpm::ExecutionPhase::Prefill;
          auto batch_result_cached = pipeline.run_batch(
              std::move(sessions.session_state_cached), tokens, phase);
          sessions.session_state_rebuilt.graph_cache.graphs.clear();
          auto batch_result_rebuilt = pipeline.run_batch(
              std::move(sessions.session_state_rebuilt), tokens, phase);
          require(batch_result_cached.logits == batch_result_rebuilt.logits,
                  "staged graph reuse changed logits "
                  "versus rebuilding the same graph");
          const auto expected = llama_get_logits_ith(ref.get(), -1);
          // The independent fused recurrent graph accumulates small FP32
          // differences from libllama over 260 positions. Short-batch checks
          // below retain 2e-4; this boundary test separately requires bitwise
          // graph-reuse equivalence.
          require(ranges::all_of(
                      ranges::views::iota(size_t{0},
                                          batch_result_cached.logits.size()),
                      [&](size_t id) {
                        return std::isfinite(batch_result_cached.logits[id]) &&
                               std::abs(batch_result_cached.logits[id] -
                                        expected[id]) <=
                                   1e-3f + 1e-3f * std::abs(expected[id]);
                      }),
                  "260-position cached/rebuilt graph diverged from reference");
          return Compared{std::move(batch_result_cached.session_state),
                          std::move(batch_result_rebuilt.session_state)};
        })

ranges::fold_left(
      std::array<int, 6>{1, 3, 32, 1, 63, 1}, pipeline.start_session(),
      [&](minicpm::SessionState session_state, int requested) {
        const int count = std::min(requested, int(pipeline.batch_capacity()));
        const auto tokens =
            ranges::views::iota(0, count) |
            ranges::views::transform([&](int i) {
              return int32_t((i + session_state.position) % 29 + 2);
            }) |
            ranges::to<std::vector<int32_t>>();
        llama_batch batch = llama_batch_get_one(
            const_cast<llama_token *>(tokens.data()), tokens.size());
        require(llama_decode(ref.get(), batch) == 0, "reference decode failed");
        const auto phase = count == 1 && session_state.position > 0
                               ? minicpm::ExecutionPhase::Decode
                               : minicpm::ExecutionPhase::Prefill;
        auto result =
            pipeline.run_batch(std::move(session_state), tokens, phase);
        const auto expected = llama_get_logits_ith(ref.get(), -1);
        ranges::for_each(ranges::views::iota(size_t{0}, result.logits.size()),
                         [&](size_t id) {
                           require(std::isfinite(result.logits[id]) &&
                                       std::isfinite(expected[id]),
                                   "non-finite logits");
                           if (std::abs(result.logits[id] - expected[id]) >
                               2e-4f + 2e-4f * std::abs(expected[id]))
                             throw std::runtime_error(
                                 "logit mismatch id=" + std::to_string(id) +
                                 " own=" + std::to_string(result.logits[id]) +
                                 " reference=" + std::to_string(expected[id]));
                         });
        return std::move(result.session_state);
      })

ranges::fold_left(lines | ranges::views::take_while([](const auto &line) {
                        return line.has_value();
                      }),
                      &input_state,
                      [](InputState *input_state, const auto &line) {
                        if (*line == "/quit")
                          input_state->done = true;
                        else
                          input_state->lines.push_back(*line);
                        return input_state;
                      })

ranges::fold_left(
      metadata, std::string{}, [](std::string acc, const auto &entry) {
        return acc + std::to_string(entry.first.size()) + ":" + entry.first +
               std::to_string(entry.second.size()) + ":" + entry.second;
      })

ranges::fold_left(
      tensors, description, [](std::string acc, const auto &entry) {
        const auto *tensor = entry.second;
        return acc + entry.first + ":" + std::to_string(tensor->type) + ":" +
               ranges::fold_left(tensor->ne, std::string{},
                                 [](std::string dims, int64_t n) {
                                   return dims + std::to_string(n) + ",";
                                 }) +
               ";";
      })

ranges::fold_left(
      layout, uint64_t{14695981039346656037ULL}, [](uint64_t hash, char c) {
        return (hash ^ static_cast<unsigned char>(c)) * 1099511628211ULL;
      })

ranges::fold_left(ranges::views::single(0), std::vector<Shard>{},
                             [&](std::vector<Shard> shards, int) {
                               shards.push_back(std::move(first));
                               return shards;
                             })

ranges::fold_left(
      ranges::views::iota(uint16_t{0}, count), std::vector<Shard>{},
      [&](std::vector<Shard> shards, uint16_t i) {
        if (i == 0) {
          shards.push_back(std::move(first));
        } else {
          std::vector<char> name(std::strlen(path) + 1); // C API output buffer
          if (llama_split_path(name.data(), name.size(), prefix.data(), i,
                               count) <= 0) {
            throw std::runtime_error("invalid GGUF split path");
          }
          shards.push_back(open_shard(name.data()));
        }
        return shards;
      })

ranges::fold_left(
      ranges::views::iota(size_t{0}, shards.size()),
      std::map<std::string, TensorSource>{}, [&](auto sources, size_t i) {
        const auto *meta = shards[i].metadata.get();
        return ranges::fold_left(
            ranges::views::iota(int64_t{0}, gguf_get_n_tensors(meta)),
            std::move(sources), [&](auto index, int64_t id) {
              if (!index
                       .emplace(gguf_get_tensor_name(meta, id),
                                TensorSource{i, id})
                       .second) {
                throw std::runtime_error("duplicate GGUF tensor");
              }
              return index;
            });
      })

ranges::fold_left(
            ranges::views::iota(int64_t{0}, gguf_get_n_tensors(meta)),
            std::move(sources), [&](auto index, int64_t id) {
              if (!index
                       .emplace(gguf_get_tensor_name(meta, id),
                                TensorSource{i, id})
                       .second) {
                throw std::runtime_error("duplicate GGUF tensor");
              }
              return index;
            })

ranges::fold_left(
      model.tensors_by_name,
      std::map<ggml_backend_buffer_type_t, std::vector<ggml_tensor *>>{},
      [](auto state, const auto &entry) {
        if (!is_expert_weight(entry.first)) {
          state[ggml_backend_buffer_get_type(entry.second->buffer)].push_back(
              entry.second);
        }
        return state;
      })

ranges::fold_left(
      groups, std::vector<WeightBlock>{}, [](auto blocks, const auto &group) {
        const auto type = group.first;
        const size_t alignment = ggml_backend_buft_get_alignment(type);
        const size_t maximum = ggml_backend_buft_get_max_size(type);
        // Limit each allocation while allowing a single larger tensor.
        const size_t target = std::min(maximum, size_t{256} * 1024 * 1024);
        return ranges::fold_left(
            group.second, std::move(blocks),
            [&](auto state, ggml_tensor *tensor) {
              const size_t bytes =
                  ggml_backend_buft_get_alloc_size(type, tensor);
              if (bytes > maximum ||
                  bytes >
                      std::numeric_limits<size_t>::max() - (alignment - 1)) {
                throw std::runtime_error(
                    "weight exceeds backend allocation limit");
              }
              const size_t padded =
                  ((bytes + alignment - 1) / alignment) * alignment;
              if (padded > maximum) {
                throw std::runtime_error(
                    "aligned weight exceeds backend allocation limit");
              }
              if (state.empty() || state.back().type != type ||
                  padded > target || state.back().bytes > target - padded) {
                state.push_back({type, 0, {}});
              }
              state.back().tensors.push_back({tensor, state.back().bytes});
              state.back().bytes += padded;
              return state;
            });
      })

ranges::fold_left(
        blocks, std::vector<Buffer>{},
        [&](auto buffers, const model_loading::WeightBlock &block) {
          Buffer buffer(ggml_backend_buft_alloc_buffer(block.type, block.bytes),
                        ggml_backend_buffer_free);
          if (!buffer)
            throw std::runtime_error("failed to allocate attention weights");

          ggml_backend_buffer_set_usage(buffer.get(),
                                        GGML_BACKEND_BUFFER_USAGE_WEIGHTS);

          ranges::for_each(
              block.tensors, [&](const model_loading::Placement &placement) {
                auto *tensor = placement.tensor;
                tensor->buffer = nullptr; // replace the upstream no_alloc dummy
                auto *address =
                    static_cast<char *>(
                        ggml_backend_buffer_get_base(buffer.get())) +
                    placement.offset;
                if (ggml_backend_tensor_alloc(buffer.get(), tensor, address) !=
                    GGML_STATUS_SUCCESS) {
                  throw std::runtime_error(
                      "failed to initialize attention weight");
                }
                model_loading::read_weight(tensor, sources.at(tensor->name),
                                           shards);
              });
          buffers.push_back(std::move(buffer));
          return buffers;
        })
